VALUES
    ('course-bili-season-7332289', 'course-bili-season-7332289', '100001', '0', 'BILI-GRW-030', 'course-category-growth', 'instructor-bili-3546615021308399', '社会学/心理学', '82 讲完整课程 · 906 小时 21 分钟', '在40集节目中，Hank Green将教你心理学！本课程基于2013年AP心理学课程大纲。学完本课程后，你将能够： * 理解人类行为和感知的生物学基础 * 解释思维、学习和情绪的标准模型 * 认识严格的心理学研究方法，', '课程简介：在40集节目中，Hank Green将教你心理学！本课程基于2013年AP心理学课程大纲。学完本课程后，你将能够： * 理解人类行为和感知的生物学基础 * 解释思维、学习和情绪的标准模型 * 认识严格的心理学研究方法，包括伦理考虑 * 识别异常心理学案例及其相关治疗 * 将心理学理论应用于社会群体 课程结构：共 1 章 82 讲，累计时长 906 小时 21 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立可落地的目标拆解与时间管理系统","掌握专注力、精力与情绪调节的实用工具","形成稳定的阅读、复盘与知识沉淀习惯","把学习成果转化为长期可复用的个人能力"]', '["希望摆脱拖延与低效忙碌的学习者","需要平衡工作与成长的职场人","在校学生与自我提升人群"]', '["愿意记录并复盘自己的真实时间开销","无需任何专业背景"]', 'beginner', 'zh-CN', 'https://s1.hdslb.com/bfs/templar/york-static/viedeo_material_default.png', '["个人成长","时间管理","学习方法","社会学","心理学"]', 3262874, 82, 144, '4.4', 52, 'BV1pqnc6bEXQ', NULL, NULL, NULL, 1, 0, 'standard', NULL, '静静带你看世界', 0, 'tenant', 'published', '2026-10-20T08:26:54.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
